import streamlit as st

st.set_page_config(page_title="Анализатор рисков БР", layout="wide")

st.title("🛢️ Экспертный анализатор рисков бурового раствора для ННБ")
st.caption("ОЦЕНКА ВЛИЯНИЯ СВОЙСТВ РАСТВОРА НА РАБОТУ КНБК, ВЗД И ТЕЛЕСИСТЕМ ПО РЕГЛАМЕНТАМ ООО 'ТРАЕКТОРЬЯ-СЕРВИС'")
st.markdown("---")

st.info("💡 Задача инженера ННБ — не бурить лаборантом, а жестко контролировать растворный сервис, понимать методики приборов и прогнозировать осложнения для КНБК.")

param = st.selectbox(
    "Выберите параметр раствора, полученный от растворной службы:",
    [
        "Не выбрано",
        "1. ПЛОТНОСТЬ БУРОВОГО РАСТВОРА",
        "2. УСЛОВНАЯ ВЯЗКОСТЬ (УВ)",
        "3. ПЛАСТИЧЕСКАЯ ВЯЗКОСТЬ (ПВ)",
        "4. ДИНАМИЧЕСКОЕ НАПРЯЖЕНИЕ СДВИГА (ДНС)",
        "5. СТАТИЧЕСКОЕ НАПРЯЖЕНИЕ СДВИГА (СНС)",
        "6. ПОКАЗАТЕЛЬ ФИЛЬТРАЦИИ ЗА 30 МИН",
        "7. ВОДОРОДНЫЙ ПОКАЗАТЕЛЬ (pH)",
        "8. СОДЕРЖАНИЕ АБРАЗИВНОГО ПЕСКА"
    ]
)

if param == "1. ПЛОТНОСТЬ БУРОВОГО РАСТВОРА":
    st.markdown("### ⚖️ Плотность бурового раствора (г/см³)")
    st.markdown("#### 🛠️ 1. Методика контроля и калибровки прибора:")
    st.write("Контролируется с помощью рычажных весов API. Весы обязаны быть чистыми, сухими. Раствор заливается до краев, закрывается крышкой, излишки выдавливаются через отверстие. Перед тестом требуйте калибровки весов на чистой пресной воде — показатель должен составить ровно **1,00 г/см³**.")
    st.markdown("#### 🔄 2. Интерактивный анализ отклонений:")
    p_status = st.radio("Какое отклонение плотности зафиксировано относительно программы промывки?", ["В пределах нормы", "Плотность выше проектной", "Плотность ниже проектной"])
    if p_status == "Плотность выше проектной":
        st.error("🚨 КРИТИЧЕСКИЙ РИСК ДЛЯ КНБК: Избыточная плотность резко повышает гидростатическое давление и эквивалентную циркуляционную плотность (ЭЦП). Это ведет к лавинообразному росту дифференциального давления на проницаемые пласты — высочайшая угроза возникновения дифференциального прихвата толстостенных элементов КНБК (УБТ, ЯСа, ВЗД) и поглощения раствора!")
    elif p_status == "Плотность ниже проектной":
        st.error("🚨 КРИТИЧЕСКИЙ РИСК ДЛЯ КНБК: Недостаточная плотность ведет к потере устойчивости стенок скважины, осыпям и кавернообразованию. В зонах каверн падает скорость восходящего потока раствора — шлам перестает выноситься, оседает обратно на забой и намертво хоронит под собой телесистему и долото!")

if param == "2. УСЛОВНАЯ ВЯЗКОСТЬ (УВ)":
    st.markdown("### 🧪 Условная вязкость (сек)")
    st.markdown("#### 🛠️ 1. Методика контроля и калибровки прибора:")
    st.write("Замеряется воронкой Марша и кружкой объемом 1 кварта (946 мл). Раствор заливают через сито до нижней риски сетки (1500 мл). Калибровка воронки проверяется на чистой воде (21±3°C) — время вытекания 946 мл воды должно составить **26 ± 0.5 сек**. Если воронка грязная или слив забит — замер недостоверен.")
    st.markdown("#### 🔄 2. Интерактивный анализ отклонений:")
    uv_trend = st.radio("Какова динамика УВ при стабильной циркуляции за последние замеры?", ["Стабильна (например: 43, 42, 44 сек)", "Постоянно растет (например: 43 -> 49 -> 53 -> 56 сек)"])
    if uv_trend == "Постоянно растет (например: 43 -> 49 -> 53 -> 56 сек)":
        st.error("🚨 КРИТИЧЕСКИЙ РИСК ДЛЯ КНБК: Раствор условно теряет стабильность. Это прямой сигнал о жестком химическом загрязнении (соль, цемент, гипс) или о том, что система очистки буровой полностью пропустила шлам. Ждите резкого роста давлений на насосах и ухудшения прохождения сигнала MWD!")

if param == "3. ПЛАСТИЧЕСКАЯ ВЯЗКОСТЬ (ПВ)":
    st.markdown("### 🔄 Пластическая вязкость (ПВ, мПа*с)")
    st.markdown("#### 🛠️ 1. Методика контроля и расчет:")
    st.write("Определяется на ротационном вискозиметре (FANN 35 или OFITE 800). Раствор перемешивают 30 сек, затем снимают показания на скоростях 600 и 300 об/мин. Пластическая вязкость рассчитывается как: **ПВ = Показание_600 - Показание_300**.")
    st.markdown("#### 🔄 2. Физика влияния и риски:")
    st.warning("💡 Физический смысл: Это 'вредная' вязкость, вызванная чисто механическим трением частиц шлама друг о друга.")
    st.error("🚨 РОСТ ПАРАМЕТРА ВЫШЕ ПРОГРАММЫ: Свидетельствует о критическом накоплении и измельчении твердой фазы в растворе. Из-за высокого механического трения возрастает ЭЦП, падает механическая скорость бурения, КНБК начинает идти с затяжками. Обязательно требуйте включения центрифуг буровой или разбавления раствора!")

if param == "4. ДИНАМИЧЕСКОЕ НАПРЯЖЕНИЕ СДВИГА (ДНС)":
    st.markdown("### ⚡ Динамическое напряжение сдвига (ДНС, фунт/100 фут²)")
    st.markdown("#### 🛠️ 1. Методика контроля и расчет:")
    st.write("Рассчитывается на основании показаний вискозиметра по формуле: **ДНС = Показание_300 - ПВ**.")
    st.markdown("#### 🔄 2. Интерактивный анализ отклонений:")
    dns_status = st.radio("Состояние показателя ДНС относительно проектного диапазона:", ["В пределах нормы", "ДНС упал ниже проектного предела", "ДНС вырос выше проектного предела"])
    if dns_status == "ДНС упал ниже проектного предела":
        st.error("🚨 КРИТИЧЕСКИЙ РИСК ДЛЯ КНБК: Снижение ДНС говорит о разрушении электрохимических связей в растворе (например, из-за скрытого притока воды). Раствор полностью теряет свою удерживающую способность! Выбуренная порода начинает мгновенно оседать в наклонной части ствола, образуя шламовую подушку. Стоит вам остановить насосы на наращивание — КНБК намертво заклинит шламаовым прихватом!")
    elif dns_status == "ДНС вырос выше проектного предела":
        st.error("🚨 КРИТИЧЕСКИЙ РИСК ДЛЯ КНБК: Ведет к резкому росту общей вязкости. Как следствие — избыточное давление на буровых насосах, критический рост ЭЦП, риски гидроразрыва пласта и поглощения раствора.")

if param == "5. СТАТИЧЕСКОЕ НАПРЯЖЕНИЕ СДВИГА (СНС)":
    st.markdown("### ⏳ Статическое напряжение сдвига (СНС, фунт/100 фут²)")
    st.markdown("#### 🛠️ 1. Методика контроля прибора:")
    st.write("Раствор перемешивают на 600 об/мин в течение 30 сек. Затем вискозиметр останавливают, выжидают **10 секунд**, включают скорость 3 об/мин и фиксируют максимальное отклонение шкалы (Gel 10s). Процедуру повторяют, но останавливают прибор уже на **10 минут** (Gel 10m).")
    st.markdown("#### 🔄 2. Интерактивный анализ отклонений:")
    sns_diff = st.radio("Оцените характер роста СНС во времени (разница между 10 сек и 10 мин):", ["Разница минимальна (Норма)", "Разница прогрессирует (Критический разрыв)"])
    if sns_diff == "Разница прогрессирует (Критический разрыв)":
        st.error("🚨 КРИТИЧЕСКИЙ РИСК ДЛЯ КНБК: Раствор в статике мгновенно превращается в жесткий, желеобразный 'холодец' (сверхвысокая тиксотропия). При восстановлении циркуляции после наращивания или СПО буровые насосы выдадут колоссальный пиковый гидроудар! Этот скачок давления способен мгновенно вывести из строя генератор и датчики MWD, порвать резиновые элементы пакеров или вызвать гидроразрыв пласта с поглощением раствора!")

if param == "6. ПОКАЗАТЕЛЬ ФИЛЬТРАЦИИ ЗА 30 МИН":
    st.markdown("### 💧 Показатель фильтрации / Водоотдача (мл/30 мин)")
    st.markdown("#### 🛠️ 1. Методика контроля и правила бокса:")
    st.write("Используется лабораторный фильтр-пресс. На стандартный диск фильтровальной бумаги (3 1/2 дюйма, строго заводского исполнения) подается стабильное давление **6,9 бар в течение 30 минут**. Объем фильтрата фиксируется в мл, а толщина оставшейся корки измеряется линейкой.")
    st.markdown("#### 🔄 2. Физика влияния и риски:")
    st.warning("💡 Физический смысл: Раствор должен мгновенно отдавать тонкую (0.5-1 мм) и непроницаемую корку, изолируя пласт.")
    st.error("🚨 РОСТ ВОДООТДАЧИ ВЫШЕ НОРМЫ: На стенках скважины нарастает толстая, рыхлая и липкая фильтрационная корка, которая сужает ствол. Это гарантирует возникновение тяжелейшего дифференциального прихвата КНБК: корпуса ВЗД, ЯСа и УБТ просто намертво 'прилипнут' к этой толстой корке под воздействием перепада давлений!")

if param == "7. ВОДОРОДНЫЙ ПОКАЗАТЕЛЬ (pH)":
    st.markdown("### 🧪 Водородный показатель (pH)")
    st.markdown("#### 🛠️ 1. Методика контроля:")
    st.write("Замеряется электронным pH-метром. Прибор перед сменой обязан калиброваться по стандарт-титрам (pH 4, pH 7, pH 10). Применение лакмусовых бумажек допускается только при абсолютно бесцветном фильтрате.")
    st.markdown("#### 🔄 2. Физика влияния и риски:")
    st.error("🚨 ПАДЕНИЕ pH НИЖЕ ПРОЕКТНОГО (Кислая среда < 7.0): Полимеры и биополимеры в кислой среде мгновенно теряют свои свойства и 'сворачиваются'. Раствор полностью теряет вязкость, реологию и удерживающую способность, а водоотдача улетает вверх. Ждите немедленных осыпей, обвалов ствола и шламаового прихвата КНБК!")

if param == "8. СОДЕРЖАНИЕ АБРАЗИВНОГО ПЕСКА":
    st.markdown("### ⏳ Содержание песка (%)")
    st.markdown("#### 🛠️ 1. Методика контроля:")
    st.write("Проба раствора из рабочей емкости перед всасывающей линией наливается в стеклянный цилиндр до отметки, разбавляется водой, взболтается и выливается на сито (74 мкм). Песок промывается, смывается воронкой обратно в измерительный цилиндр, и после оседания считывается объемный процент.")
    st.markdown("#### 🔄 2. Интерактивный анализ отклонений:")
    sand_val = st.number_input("Введите фактическое содержание песка из рапорта лаборанта, %:", min_value=0.0, value=0.3, step=0.1)
    if sand_val > 1.0:
        st.error(f"🚨 КРИТИЧЕСКИЙ РЕЗУЛЬТАТ (Песок {sand_val}% > 1.0%): Абразивный песок работает внутри КНБК как наждак! Такое высокое содержание абразива вызовет мгновенную эрозию и размыв корпуса бурового долота, уничтожение гидроканалов и датчиков MWD, и, самое опасное — стремительное стирание и лавинообразное отслоение резиновой обкладки статора ВЗД с выносом ошметков эластомера на сита и полным отказом двигателя!")
    else:
        st.success(f"✔️ Содержание песка {sand_val}% находится в безопасных пределах (до 1.0%). Абразивный износ узлов КНБК минимален.")
